import { endpointModule, WsEndpoint, WsEndpointController } from "@techgoose-labs/rune";
import { JoinDto } from "@/src/chat/dto/join.ts";
import { JoinedDto } from "@/src/chat/dto/joined.ts";
import { ChatDto } from "@/src/chat/dto/chat.ts";
import { EchoDto } from "@/src/chat/dto/echo.ts";
import { LeaveDto } from "@/src/chat/dto/leave.ts";
import { LeftDto } from "@/src/chat/dto/left.ts";
import { join as roomJoin } from "@/src/chat/domain/coordinators/room-join/mod.ts";
import { send as roomSend } from "@/src/chat/domain/coordinators/room-send/mod.ts";
import { leave as roomLeave } from "@/src/chat/domain/coordinators/room-leave/mod.ts";

@WsEndpointController("rooms/:room")
export class ChatSocket {
  /**
   * Topic "join" → coordinator room.join (named by the body [REQ]).
   * @param data JoinDto — a request to join a room (the inbound message payload)
   * @returns JoinedDto — the join acknowledgement (sent back to the sender)
   */
  // from corpus/valid/ws-chat.rune:4
  @WsEndpoint({ topic: "join", input: JoinDto, output: JoinedDto })
  join(data: JoinDto): Promise<JoinedDto> {
    return roomJoin(data);
  }

  /**
   * Topic "send" → coordinator room.send (named by the body [REQ]).
   * @param data ChatDto — a chat line typed by a member (the inbound message payload)
   * @returns EchoDto — the line echoed back with a server timestamp (sent back to the sender)
   */
  // from corpus/valid/ws-chat.rune:6
  @WsEndpoint({ topic: "send", input: ChatDto, output: EchoDto })
  send(data: ChatDto): Promise<EchoDto> {
    return roomSend(data);
  }

  /**
   * Topic "leave" → coordinator room.leave (named by the body [REQ]).
   * @param data LeaveDto — a request to leave a room (the inbound message payload)
   * @returns LeftDto — the leave acknowledgement (sent back to the sender)
   */
  // from corpus/valid/ws-chat.rune:8
  @WsEndpoint({ topic: "leave", input: LeaveDto, output: LeftDto })
  leave(data: LeaveDto): Promise<LeftDto> {
    return roomLeave(data);
  }
}

export const chatModule = endpointModule("Chat", [ChatSocket]);

